// This code is secure: the path is checked against a whitelist of allowed
// characters and the maximum length, and the final path is resolved
// against the server's base path before any file operations.

import java.io.*;
import java.nio.file.*;
import java.util.regex.*;

public class SecurePathTraversal {
    private static final String ALLOWED_CHARS = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-._";
    private static final int MAX_PATH_LENGTH = 255;

    public static void main(String[] args) throws Exception {
        String path = args[0];

        // Validate the input: only allowed characters and within length limits.
        if (!path.matches("^[^" + ALLOWED_CHARS.replace(" ", "\\s") + "]*$")
                || path.length() > MAX_PATH_LENGTH) {
            throw new IllegalArgumentException("Invalid path: " + path);
        }

        String resolved = Paths.get(path).normalize().toString();
        File target = new File(resolved);

        // Resolve against the server's base path to prevent remote file access.
        File base = new File(System.getProperty("user.dir"));
        File target2 = new File(base, resolved);

        // Only copy if the resolved path is within the server's directory.
        if (target2.exists() && target2.equals(target)) {
            Files.copy(Paths.get(path), Paths.get(target2.toURI()));
        }
    }
